using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading;
using System.Threading.Tasks;
using BMDSwitcherAPI;


namespace SwitcherRecordCSharp
{
	#region exceptions
	class SwitcherConnectException : Exception
	{
		public SwitcherConnectException() : base() { }
		public SwitcherConnectException(string message) : base(message) { }
	}

	class SwitcherRecordInvalidException : Exception
	{
		public SwitcherRecordInvalidException() : base() { }
		public SwitcherRecordInvalidException(string message) : base(message) { }

	}
	#endregion

	#region event args
	public class RecordAllISOInputsEventArgs : EventArgs
	{
		private readonly bool recordAllISOInputs;
		public RecordAllISOInputsEventArgs(bool recordAllISOInputs) => this.recordAllISOInputs = recordAllISOInputs;
	}

	public class RecordInAllCamerasEventArgs : EventArgs
	{
		private readonly bool recordInAllCameras;
		public RecordInAllCamerasEventArgs(bool recordInAllCameras) => this.recordInAllCameras = recordInAllCameras;
	}

	public class RecordingDurationEventArgs : EventArgs
	{
		private readonly ulong duration;
		public RecordingDurationEventArgs(ulong duration) => this.duration = duration;
	}

	public class TotalRecordingTimeEventArgs : EventArgs
	{
		private readonly uint time;
		public TotalRecordingTimeEventArgs(uint time) => this.time = time;
	}

	public class ActiveDiskIndexEventArgs : EventArgs
	{
		private readonly uint index;
		public ActiveDiskIndexEventArgs(uint index) => this.index = index;
	}

	public class RecordingTimecodeEventArgs : EventArgs
	{
		private readonly byte hours;
		private readonly byte minutes;
		private readonly byte seconds;
		private readonly byte frames;
		private readonly bool dropFrame;

		public RecordingTimecodeEventArgs(byte hours, byte minutes, byte seconds, byte frames, bool dropFrame)
		{
			this.hours = hours;
			this.minutes = minutes;
			this.seconds = seconds;
			this.frames = frames;
			this.dropFrame = dropFrame;
		}
	}

	public class FilenameEventArgs : EventArgs
	{
		private readonly string recordingFilename;
		public FilenameEventArgs(string recordingFilename) => this.recordingFilename = recordingFilename;
	}

	public class DiskAvailableEventArgs : EventArgs
	{
		public DiskAvailableEventArgs(IBMDSwitcherRecordDisk disk) => Disk = disk;
		public IBMDSwitcherRecordDisk Disk { get; private set; }
	}

	public class DiskRemovedEventArgs : EventArgs
	{
		public DiskRemovedEventArgs(uint diskID) => DiskID = diskID;
		public uint DiskID { get; private set; }
	}

	#endregion

	class SwitcherRecordAVDevice
	{
		private readonly IBMDSwitcher switcher;
		private readonly IBMDSwitcherCallback switcherCallback;
		private readonly IBMDSwitcherRecordAV switcherRecordAV;
		private readonly IBMDSwitcherRecordAVCallback switcherRecordAVCallback;

		private Dictionary<uint, IBMDSwitcherRecordDisk> switcherRecordDisks;
		private readonly IBMDSwitcherRecordDiskCallback switcherRecordDiskCallback;

		private const uint Disk1WorkingSetIndex = 0;
		private const uint Disk2WorkingSetIndex = 1;

		private readonly IReadOnlyDictionary<_BMDSwitcherConnectToFailure, string> ConnectToFailureString = new Dictionary<_BMDSwitcherConnectToFailure, string>()
		{
			{ _BMDSwitcherConnectToFailure.bmdSwitcherConnectToFailureNoResponse,           "No response from Switcher" },
			{ _BMDSwitcherConnectToFailure.bmdSwitcherConnectToFailureIncompatibleFirmware, "Switcher has incompatible firmware" },
		};

		public SwitcherRecordAVDevice(string ipAddress, SwitcherRecordAVMonitor recordAVMonitor, SwitcherRecordDiskMonitor recordDiskMonitor, SwitcherMonitor monitor)
		{
			// Create switcher discovery object
			IBMDSwitcherDiscovery discovery = new CBMDSwitcherDiscovery();
			_BMDSwitcherConnectToFailure failureReason = _BMDSwitcherConnectToFailure.bmdSwitcherConnectToFailureNoResponse;

			// Connect to switcher
			try
			{
				discovery.ConnectTo(ipAddress, out switcher, out failureReason);
			}
			catch (Exception)
			{
				throw new SwitcherConnectException(ConnectToFailureString.TryGetValue(failureReason, out string value) ? value : "Connection failed for unknown reason");
			}

			switcherRecordAV = switcher as IBMDSwitcherRecordAV;

			if (switcherRecordAV == null)
			{
				// Switcher does not support RecordAV interface
				throw new SwitcherRecordInvalidException("Switcher does not have record interface");
			}

			switcherCallback = monitor;
			switcher.AddCallback(switcherCallback);

			switcherRecordAVCallback = recordAVMonitor;
			switcherRecordAV.AddCallback(switcherRecordAVCallback);

			switcherRecordDiskCallback = recordDiskMonitor;
			switcherRecordDisks = new Dictionary<uint, IBMDSwitcherRecordDisk>();
			foreach (var disk in Disks)
			{
				disk.GetId(out uint diskId);
				switcherRecordDisks.Add(key: diskId, value: disk);
				disk.AddCallback(switcherRecordDiskCallback);
			}
		}

		public void Disable()
		{
			// Disconnect callbacks from further notifications
			switcher.RemoveCallback(switcherCallback);
			switcherRecordAV.RemoveCallback(switcherRecordAVCallback);
			foreach (var diskValue in switcherRecordDisks.Values)
			{
				diskValue.RemoveCallback(switcherRecordDiskCallback);
			}
		}

		public List<uint> AvailableDiskIds => switcherRecordDisks.Keys.ToList();

		internal async Task TaskRecord(params CancellationToken[] cancellationTokens)
		{
			using (CancellationTokenSource linkedCancelToken = CancellationTokenSource.CreateLinkedTokenSource(cancellationTokens))
			{
				// Maintain task to periodically request recording duration
				while (true)
				{
					switcherRecordAV.RequestDuration();
					await Task.Delay(TimeSpan.FromMilliseconds(1000), linkedCancelToken.Token);
				}
			}
		}

		public void DiskWithIDAvailable(uint diskId)
		{
			switcherRecordAV.CreateIterator(typeof(IBMDSwitcherRecordDiskIterator).GUID, out IntPtr diskIteratorPtr);
			if (!(Marshal.GetObjectForIUnknown(diskIteratorPtr) is IBMDSwitcherRecordDiskIterator diskIterator))
				return;

			diskIterator.GetById(diskId, out IBMDSwitcherRecordDisk disk);
			switcherRecordDisks.Add(key: diskId, value: disk);
			disk.AddCallback(switcherRecordDiskCallback);
		}

		public void DiskWithIDRemoved(uint diskId)
		{
			if (switcherRecordDisks.TryGetValue(diskId, out IBMDSwitcherRecordDisk disk))
			{
				disk.RemoveCallback(switcherRecordDiskCallback);
				switcherRecordDisks.Remove(diskId);
			}
		}

		public void StartRecording() =>	switcherRecordAV.StartRecording();
		public void StopRecording() => switcherRecordAV.StopRecording();
		public void SwitchDisk() => switcherRecordAV.SwitchDisk();

		public string ProductName
		{
			get
			{
				switcher.GetProductName(out string productName);
				return productName;
			}
		}

		public bool IsRecording
		{
			get
			{
				switcherRecordAV.IsRecording(out int recording);
				return Convert.ToBoolean(recording);
			}
		}

		public string RecordingFilename
		{
			get
			{
				switcherRecordAV.GetFilename(out string filename);
				return filename;
			}
			set => switcherRecordAV.SetFilename(value);
		}

		public bool RecordInAllCameras
		{
			get
			{
				switcherRecordAV.GetRecordInAllCameras(out int recordInAllCameras);
				return Convert.ToBoolean(recordInAllCameras);
			}
			set => switcherRecordAV.SetRecordInAllCameras(Convert.ToInt32(value));
		}

		public bool RecordAllISOInputs
		{
			get
			{
				switcherRecordAV.GetRecordAllISOInputs(out int recordAllISOInputs);
				return Convert.ToBoolean(recordAllISOInputs);
			}
			set => switcherRecordAV.SetRecordAllISOInputs(Convert.ToInt32(value));
		}

		public bool SupportsISORecording
		{
			get
			{
				switcherRecordAV.DoesSupportISORecording(out int supportsISORecording);
				return Convert.ToBoolean(supportsISORecording);
			}
		}

		public uint Disk1WorkingSet
		{
			get
			{
				switcherRecordAV.GetWorkingSetDisk(Disk1WorkingSetIndex, out uint diskId);
				return diskId;
			}
			set => switcherRecordAV.SetWorkingSetDisk(Disk1WorkingSetIndex, value);
		}

		public uint Disk2WorkingSet
		{
			get
			{
				switcherRecordAV.GetWorkingSetDisk(Disk2WorkingSetIndex, out uint diskId);
				return diskId;
			}
			set => switcherRecordAV.SetWorkingSetDisk(Disk2WorkingSetIndex, value);
		}

		public uint ActiveDiskIndex
		{
			get
			{
				switcherRecordAV.GetActiveDiskIndex(out uint workingSetIndex);
				return workingSetIndex;
			}
		}

		public _BMDSwitcherRecordAVState RecordStatus
		{
			get
			{
				switcherRecordAV.GetStatus(out _BMDSwitcherRecordAVState state, out _);
				return state;
			}
		}

		public string TimecodeHMSString
		{
			get
			{
				switcherRecordAV.GetTimeCode(out byte hours, out byte minutes, out byte seconds, out _, out _);
				return String.Format("{0:D2}:{1:D2}:{2:D2}", hours, minutes, seconds);
			}
		}

		public uint TotalRecordingTimeAvailable
		{
			get
			{
				switcherRecordAV.GetTotalRecordingTimeAvailable(out uint totalRecordingTimeAvailable);
				return totalRecordingTimeAvailable;
			}
		}

		public string GetDiskVolumeName(uint diskId)
		{
			if (!switcherRecordDisks.TryGetValue(diskId, out IBMDSwitcherRecordDisk disk))
				return "Invalid DiskId";
			
			disk.GetVolumeName(out string volumeName);
			return volumeName;
		}

		public uint GetDiskRecordingTimeAvailable(uint diskId)
		{
			if (!switcherRecordDisks.TryGetValue(diskId, out IBMDSwitcherRecordDisk disk))
				return 0;

			disk.GetRecordingTimeAvailable(out uint recordingTimeAvailable);
			return recordingTimeAvailable;
		}

		public _BMDSwitcherRecordDiskStatus GetDiskStatus(uint diskId)
		{
			if (!switcherRecordDisks.TryGetValue(diskId, out IBMDSwitcherRecordDisk disk))
				return _BMDSwitcherRecordDiskStatus.bmdSwitcherRecordDiskIdle;

			disk.GetStatus(out _BMDSwitcherRecordDiskStatus status);
			return status;
		}

		private IEnumerable<IBMDSwitcherRecordDisk> Disks
		{
			get
			{
				// Create a record disk iterator
				switcherRecordAV.CreateIterator(typeof(IBMDSwitcherRecordDiskIterator).GUID, out IntPtr diskIteratorPtr);
				if (!(Marshal.GetObjectForIUnknown(diskIteratorPtr) is IBMDSwitcherRecordDiskIterator diskIterator))
					yield break;

				// Iterate through all disks
				while (true)
				{
					diskIterator.Next(out IBMDSwitcherRecordDisk disk);

					if (disk != null)
						yield return disk;
					else
						yield break;
				}
			}
		}
	}
}
